import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Frequently asked questions","description":"","frontmatter":{"pageId":"faq","contentRevision":5},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md"}'),o={name:"en/faq.md"};function s(i,e,l,d,h,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p><strong>Must everyone play together?</strong> Not for independent colonies or asynchronous economy; yes for live and coop.</p><p><strong>Can I continue offline?</strong> Canonical state belongs to the server. Do not substitute a local save: it may conflict with items and transactions already settled.</p><p><strong>Where is a transfer after a disconnect?</strong> Reconnect and inspect mail, market and operation state first. The outbox retries an unanswered request with the same identifier.</p><p><strong>Does an alliance color mean territorial ownership?</strong> No. It is an informational overlay of voluntarily published influence.</p><h2 id="choosing" tabindex="-1">Do we need a server and a shared schedule? <a class="header-anchor" href="#choosing" aria-label="Permalink to &quot;Do we need a server and a shared schedule? {#choosing}&quot;">​</a></h2><p><strong>Can one player invite another without a server?</strong> Rimlink requires a dedicated server. It may run on a participant&#39;s computer, but both games must reach it. The browser panel administers that server; it is not the game.</p><p><strong>Must everyone be online together?</strong> Not for commerce, messages, queued raids or independent colonies. Live and coop require the host online at home. Their colony cannot continue autonomously after they leave.</p><p><strong>Can we share everything?</strong> Coop grants control of explicitly assigned pawns, not wallets, item transfers, admin authority or save ownership.</p><p><strong>Is a subscription required?</strong> The mod and wiki are free. The game, DLC and any paid hosting are separate purchases, not included with Rimlink.</p><h2 id="mistakes" tabindex="-1">Why are familiar workarounds unsafe? <a class="header-anchor" href="#mistakes" aria-label="Permalink to &quot;Why are familiar workarounds unsafe? {#mistakes}&quot;">​</a></h2><p><strong>Restore goods using an old save?</strong> No: another player may already have received them. Resolve the original operation through replay/reconnection.</p><p><strong>Delete the outbox to clear an error?</strong> No: it is evidence of an unfinished request. Preserve the folder and diagnose the refusal.</p><p><strong>Trust a changed certificate because the server name is familiar?</strong> Verify the new fingerprint with the administrator through another channel first.</p><p><strong>Does a guild color prevent entry?</strong> No. Influence is informational, not land ownership.</p><p><strong>Do old promotional images show gameplay?</strong> Concept art presents the idea. Wiki diagrams are not claimed as game UI; a verified gameplay screenshot gallery has not yet been collected.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Deleting journals or manually duplicating transfers can cause loss or duplication. Give an administrator the operation ID and time, never a password or token.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./players/saves-recovery">Saves and recovery</a></li><li><a href="./players/troubleshooting">Player troubleshooting</a></li><li><a href="./players/guild-influence">Guild influence</a></li></ul>',22)])])}const m=a(o,[["render",s]]);export{p as __pageData,m as default};
